import{_ as t,c as r,o,ag as e}from"./chunks/framework.DPDPlp3K.js";const c=JSON.parse('{"title":"性能问题排查案例","description":"","frontmatter":{},"headers":[],"relativePath":"shopify/storefronts/性能问题排查(性能优化).md","filePath":"shopify/storefronts/性能问题排查(性能优化).md"}'),p={name:"shopify/storefronts/性能问题排查(性能优化).md"};function s(n,a,h,i,d,_){return o(),r("div",null,a[0]||(a[0]=[e('<h1 id="性能问题排查案例" tabindex="-1">性能问题排查案例 <a class="header-anchor" href="#性能问题排查案例" aria-label="Permalink to &quot;性能问题排查案例&quot;">​</a></h1><h2 id="排查-add-to-cart-延迟的根源" tabindex="-1">排查 Add to Cart 延迟的根源 <a class="header-anchor" href="#排查-add-to-cart-延迟的根源" aria-label="Permalink to &quot;排查 Add to Cart 延迟的根源&quot;">​</a></h2><h3 id="_1-🔍-先定位延迟类型" tabindex="-1">1. 🔍 先定位延迟类型 <a class="header-anchor" href="#_1-🔍-先定位延迟类型" aria-label="Permalink to &quot;1. 🔍 先定位延迟类型&quot;">​</a></h3><p>打开浏览器开发者工具（F12）→ Network 标签，点击&quot;加入购物车&quot;按钮，观察：</p><p>请求发送到 /cart/add.js 的响应时间是多少？ 是请求本身慢（后端问题），还是请求很快但页面响应慢（前端/JS 问题）？</p><h3 id="_2-🛒-常见原因排查" tabindex="-1">2. 🛒 常见原因排查 <a class="header-anchor" href="#_2-🛒-常见原因排查" aria-label="Permalink to &quot;2. 🛒 常见原因排查&quot;">​</a></h3><p>前端/主题层面：</p><p>主题 JS 冲突：多个 App 注入了 cart 相关脚本，互相等待 Cart drawer 渲染慢：加入购物车后触发了复杂的 DOM 更新或动画 第三方 App 脚本阻塞：如推荐、评价、捆绑销售类 App 监听了 cart 事件 App 层面：</p><p>检查已安装的 App 是否有 cart hook / cart transform（如 Bundle、Upsell 类 App） 在 Shopify Admin → Settings → Custom data → Cart transforms 查看是否有激活的 cart transform 网络/服务器层面：</p><p>测试不同地区的响应时间（AU 用户访问 au.ecoflow.com 是否有 CDN 覆盖？） 检查 Shopify Status Page 是否有区域性故障</p><h3 id="_3-🧪-快速验证方法" tabindex="-1">3. 🧪 快速验证方法 <a class="header-anchor" href="#_3-🧪-快速验证方法" aria-label="Permalink to &quot;3. 🧪 快速验证方法&quot;">​</a></h3><p>禁用 App 脚本测试： 在主题编辑器中临时切换到 Shopify 默认主题（Dawn），测试同一产品的加入购物车速度，如果明显变快 → 问题在当前主题或 App 脚本。</p><p>逐一禁用 App： 在 App 管理页面逐一暂停可疑 App，每次测试 ATC 速度，定位具体是哪个 App 造成的。</p><h3 id="_4-📊-量化延迟" tabindex="-1">4. 📊 量化延迟 <a class="header-anchor" href="#_4-📊-量化延迟" aria-label="Permalink to &quot;4. 📊 量化延迟&quot;">​</a></h3><p>用 Chrome DevTools 的 Performance 录制，点击 ATC 按钮，查看：</p><p>Long Tasks（超过 50ms 的任务） 哪个脚本占用了主线程时间</p><hr><p>下面我给你一份 <strong>“网页性能优化指标 + DevTools Performance + Lighthouse + PageSpeed Insights”</strong> 的<strong>体系化介绍</strong>。<br> 你可以把它当成 <strong>测试 / 前端 / 性能评估的速读指南</strong> ✅</p><hr>',19)]))}const f=t(p,[["render",s]]);export{c as __pageData,f as default};
